17		@ActivationConfigProperty(propertyName = "destinationType", propertyValue = "javax.jms.Topic"),
18		@ActivationConfigProperty(propertyName = "acknowledgeMode", propertyValue = "Auto-acknowledge")})
19	public class OrderServiceMDB implements MessageListener {
20	
21		@Inject
22		Logger log;
23	
24		@Inject
25		OrderService orderService;
26	
27		@Inject
28		CatalogService catalogService;
29	
30		@Override
31		public void onMessage(Message rcvMessage) {
32			log.info("Order message received");
33			TextMessage msg = null;
34			try {
35					if (rcvMessage instanceof TextMessage) {
36							msg = (TextMessage) rcvMessage;
37							String orderStr = msg.getBody(String.class);
38							log.info("Received order: " + orderStr);
39							Order order = Transformers.jsonToOrder(orderStr);
40							log.info("Order object is " + order);
41							orderService.save(order);
42							order.getItemList().forEach(orderItem -> {
43								catalogService.updateInventoryItems(orderItem.getProductId(), orderItem.getQuantity());
44							});
45					}
46			} catch (JMSException e) {
47				// Re-throw as RuntimeException so the MDB container marks the message for redelivery
48				throw new RuntimeException("Failed to process order message", e);
49			}
